const explanations = {
  "963db4db-8d1b-4e80-8c5c-f49315b93852": { // Familie Geissler oder Dippold
    21: { kw: "auf", ex: `"die Antwort auf etwas" تعبير اسمي ثابت (الرد على شيء) حيث يُستخدم "auf" مع الاسم "Antwort" للدلالة على موضوع الرد. أما "wegen" (بسبب) تفيد السببية لا موضوع الرد، و"von" (من) تدل على المصدر لا الموضوع. المحفز النحوي: الاسم "Antwort" في تعبير "Antwort auf etwas" يتطلب حرف الجر الثابت "auf" حصراً.`, gs: "تلازم لفظي: Antwort auf" },
    22: { kw: "ab", ex: `"etwas abschließen" فعل مركب منفصل يعني "ينهي/يُتم"، وهو المناسب لإنهاء الدراسة (schließe...ab). أما "zu"/"aus" لا يشكلان فعلاً مركباً صحيحاً بهذا المعنى مع "schließen" (zuschließen=يُقفل، ausschließen=يستبعد). المحفز النحوي: البادئة المنفصلة في نهاية الجملة تحدد الفعل المركب "abschließen".`, gs: "فعل مركب منفصل: abschließen" },
    23: { kw: "ein bisschen", ex: `"ein bisschen" ظرف كمية بمعنى "قليلاً" ويصف تحسناً متواضعاً مرغوباً. أما "kaum" (بالكاد) نفي شبه تام يتعارض مع الرغبة الإيجابية، و"fast" (تقريباً) تصف اقتراباً من اكتمال فعل ولا معنى له مع فعل مستمر "verbessern". المحفز النحوي: الفعل الإيجابي "verbessern" يستدعي ظرف كمية إيجابياً لا نفياً.`, gs: "ظرف كمية إيجابي: ein bisschen" },
    24: { kw: "machen", ex: `"einen Kurs machen" تعبير ثابت يعني "يلتحق بدورة"، مناسب مع "einen Sprachkurs". أما "unterrichten" (يُدرّس) فعل المعلم لا الطالب، و"lernen" (يتعلم) لا يترافق عادة مباشرة مع "einen Kurs" بهذا الشكل. المحفز النحوي: التلازم اللفظي "einen Kurs machen" هو الصحيح للالتحاق كطالب.`, gs: "تلازم لفظي: einen Kurs machen" },
    25: { kw: "an", ex: `"eine Frage an jemanden" تعبير ثابت (سؤال موجه لشخص)، وحرف الجر "an" يدل على المُخاطَب. أما "über" (حول) يدل على الموضوع، و"für" لا يناسب. المحفز النحوي: تعبير "eine Frage an jmdn." يحدد "an" حصراً.`, gs: "تلازم لفظي: eine Frage an" },
    26: { kw: "irgendjemandem", ex: `الفعل "ausleihen" هنا يحتاج شخصاً (bei+Dativ يدل على مصدر الاستعارة)، فالأنسب "irgendjemandem" (من أي شخص). أما "irgendwo" ظرف مكان لا شخص، و"irgendetwas" ضمير لشيء لا شخص. المحفز النحوي: "bei"+استعارة تستدعي ضمير شخص غير محدد.`, gs: "ضمير غير محدد للأشخاص بعد bei: irgendjemandem" },
    27: { kw: "dass", ex: `"danke, dass..." تركيب ثابت للشكر على فعل محدد، وأداة الربط "dass" تُدخل جملة موضوع الشكر. أما "falls" (في حال) لا تناسب شكراً مؤكداً، و"dafür" ضمير ظرفي لا يُدخل جملة تابعة. المحفز النحوي: تعبير "danke, dass..." يتطلب "dass".`, gs: "تعبير ثابت: danke, dass..." },
    28: { kw: "schon", ex: `"schon gebucht" ظرف يفيد إنجاز الفعل مسبقاً، مناسب لإخبار عن ترتيبات مكتملة. أما "noch" يفيد عدم الإنجاز (معنى معاكس)، و"bevor" أداة ربط زمنية لا ظرف مستقل. المحفز النحوي: Perfekt (habe...gebucht) مع سياق إخباري يستدعي "schon".`, gs: "ظرف إنجاز مع Perfekt: schon" },
    29: { kw: "vor", ex: `"etwas vorschlagen" فعل مركب منفصل (يقترح)، والبادئة "vor" تنتقل لنهاية الجملة (schlage...vor). أما "zu"/"nach" لا يشكلان فعلاً مركباً صحيحاً هنا. المحفز النحوي: الفعل المركب "vorschlagen" يتطلب البادئة "vor" في النهاية.`, gs: "فعل مركب منفصل: vorschlagen" },
    30: { kw: "mehr", ex: `"ein bisschen mehr" تركيب مقارنة (أكثر قليلاً) يناسب إرسال صور إضافية. أما "weniger" معنى معاكس، و"viel" لا يتناسق مع "ein bisschen" في نفس التركيب. المحفز النحوي: "ein bisschen+Komparativ" يحدد "mehr".`, gs: "تركيب مقارنة تصاعدي: ein bisschen mehr" },
  },
  "6ccc22ad-36c9-426c-8c47-e9c0b8231635": { // Ferdinand Original
    21: { kw: "um", ex: `"um...zu+Infinitiv" تركيب غرضي ثابت (من أجل أن) يصف هدف العمل (دفع الإيجار)، وفاعل الجملتين نفسه. أما "anstatt...zu" (بدلاً من) مفاضلة عكسية، و"ohne...zu" (بدون أن) نفي، وكلاهما معنى معاكس. المحفز النحوي: تطابق الفاعل يستدعي "um...zu".`, gs: "تركيب غرضي بفاعل مشترك: um...zu" },
    22: { kw: "wie", ex: `"wie" أداة استفهام غير مباشر (كيف كنت سأتحمل ذلك). أما "dass" تُدخل جملة مؤكدة لا سؤالاً، و"während" (بينما) لا تناسب. المحفز النحوي: "weiß nicht"+سؤال ضمني عن الكيفية (Konjunktiv II würde) يستدعي "wie".`, gs: "أداة استفهام غير مباشر: wie" },
    23: { kw: "aber", ex: `"aber" عطف تضادي يربط صفتين متعارضتين، متوافق مع "anderseits" اللاحقة. أما "denn" سببية، و"und" عطف بسيط لا يعبّر عن التضاد. المحفز النحوي: التضاد مع "anderseits" يستدعي "aber".`, gs: "أداة عطف تضادية: aber (مع anderseits)" },
    24: { kw: "unbedingt", ex: `"unbedingt" ظرف (بأي ثمن) يعبر عن رغبة طفولية قوية. أما "bestimmt" تأكيد لحقيقة لا لشدة رغبة، و"völlig" يصف اكتمالاً. المحفز النحوي: رغبة طفولية قوية تستدعي "unbedingt" مع "wollen".`, gs: "ظرف شدة مع wollen: unbedingt" },
    25: { kw: "mich", ex: `"sich täuschen" فعل انعكاسي، وفاعله "ich" يستدعي "mich" (نصب، متكلم). أما "dich"/"sich" لا يتطابقان مع "ich". المحفز النحوي: تطابق الضمير الانعكاسي مع الفاعل "ich" → "mich".`, gs: "تطابق ضمير انعكاسي: ich → mich" },
    26: { kw: "als", ex: `"als" أداة ربط زمنية لحدث/فترة ماضية فريدة (كنا في المدرسة)، مع Präteritum/Perfekt. أما "wenn" للتكرار/الحاضر، و"wie" لا معنى زمنياً لها. المحفز النحوي: فترة ماضية واحدة تستدعي "als".`, gs: "أداة زمنية لفترة ماضية فريدة: als" },
    27: { kw: "kommenden", ex: `"kommende Wochenenden" صفة تصف المستقبل، مناسبة للسؤال عن خطط قادمة. أما "baldigen" أقل شيوعاً هنا، و"vergangenen" (الماضية) معنى معاكس. المحفز النحوي: السؤال عن "Pläne" يستلزم إشارة مستقبلية "kommenden".`, gs: "صفة مستقبلية: kommenden" },
    28: { kw: "dazu", ex: `"Lust zu etwas haben" والضمير الظرفي "dazu" يشير لفكرة اللقاء السابقة. أما "danach"/"darüber" لا يرتبطان بـ"Lust haben" بنفس الطريقة. المحفز النحوي: تعبير "Lust zu etwas" يحدد "zu"، فالضمير الظرفي "dazu".`, gs: "ضمير ظرفي: Lust dazu haben" },
    29: { kw: "sondern", ex: `"nicht nur...sondern auch" أداة ربط مزدوجة ثابتة، شريك إلزامي لـ"nicht nur" السابقة. أما "aber"/"oder" لا يرتبطان نحوياً بـ"nicht nur". المحفز النحوي: وجود "nicht nur" يفرض "sondern auch".`, gs: "أداة ربط مزدوجة: nicht nur...sondern auch" },
    30: { kw: "für", ex: `"etwas für jemanden" تعبير ثابت (شيء يناسب شخصاً)، وحرف الجر "für" للملاءمة الشخصية. أما "gegen"/"ohne" لا يناسبان. المحفز النحوي: التعبير العامي "etwas für jemanden" يحدد "für".`, gs: "تعبير ثابت: etwas für jemanden" },
  },
  "df4ef1c3-270a-4e89-8f58-90b11284cc78": { // Ferdinand معدل - same passage, some different distractor sets, gap 29 SKIPPED (data issue)
    21: { kw: "um", ex: `"um...zu+Infinitiv" تركيب غرضي ثابت يصف هدف العمل (دفع الإيجار)، وفاعل الجملتين نفسه. أما "damit" تُستخدم عند اختلاف الفاعلين وهنا الفاعل واحد، و"für" لا تُدخل جملة غرضية بهذا الشكل. المحفز النحوي: تطابق الفاعل يستدعي "um...zu".`, gs: "تركيب غرضي بفاعل مشترك: um...zu" },
    22: { kw: "wie", ex: `"wie" أداة استفهام غير مباشر (كيف كنت سأتحمل ذلك). أما "wann" تسأل عن التوقيت لا الكيفية، و"wo" أداة مكانية. المحفز النحوي: "weiß nicht"+سؤال ضمني عن الكيفية يستدعي "wie".`, gs: "أداة استفهام غير مباشر: wie" },
    23: { kw: "doch", ex: `"doch" أداة عطف/تخفيف تضادية تربط صفتين متعارضتين هنا (متعب، لكن من جهة أخرى ممتع)، مدعومة بـ"anderseits" اللاحقة. أما "damit" (لكي) لا معنى غرضي هنا، و"denn" سببية لا تضادية. المحفز النحوي: التضاد مع "anderseits" يستدعي أداة تضاد مثل "doch".`, gs: "أداة تضاد: doch (مع anderseits)" },
    24: { kw: "unbedingt", ex: `"unbedingt" ظرف (بأي ثمن) يعبر عن رغبة طفولية قوية. أما "bestimmt" تأكيد لحقيقة، و"völlig" اكتمال. المحفز النحوي: رغبة طفولية قوية تستدعي "unbedingt".`, gs: "ظرف شدة مع wollen: unbedingt" },
    25: { kw: "mich", ex: `"sich täuschen" فعل انعكاسي، وفاعله "ich" يستدعي "mich". أما "dich"/"sich" لا يتطابقان مع "ich". المحفز النحوي: تطابق الضمير الانعكاسي مع الفاعل.`, gs: "تطابق ضمير انعكاسي: ich → mich" },
    26: { kw: "als", ex: `"als" أداة ربط زمنية لفترة ماضية فريدة (كنا في المدرسة). أما "da" (بما أن) سببية لا زمنية بهذا المعنى، و"wenn" للتكرار/الحاضر. المحفز النحوي: فترة ماضية واحدة تستدعي "als".`, gs: "أداة زمنية لفترة ماضية فريدة: als" },
    27: { kw: "kommenden", ex: `"kommende Wochenenden" صفة تصف المستقبل، مناسبة للسؤال عن خطط قادمة. أما "jetzigen" (الحالية) و"letzten" (الأخيرة/الماضية) لا يناسبان سؤالاً عن خطط مستقبلية. المحفز النحوي: السؤال عن "Pläne" يستلزم "kommenden".`, gs: "صفة مستقبلية: kommenden" },
    28: { kw: "dazu", ex: `"Lust zu etwas haben"، والضمير الظرفي "dazu" يشير لفكرة اللقاء السابقة. أما "danach"/"darüber" لا يرتبطان بـ"Lust haben". المحفز النحوي: تعبير "Lust zu etwas" يحدد الضمير الظرفي "dazu".`, gs: "ضمير ظرفي: Lust dazu haben" },
    30: { kw: "einfach", ex: `"einfach" هنا ظرف بمعنى "ببساطة" يخفف من نبرة الاقتراح الودي (Wäre das was einfach für dich = هل هذا سيكون ببساطة شيئاً يناسبك). أما "einen" أداة تنكير لا تصلح ظرفاً هنا، و"einzig" (الوحيد) لا يناسب النبرة الودية العفوية. المحفز النحوي: النبرة العفوية غير الرسمية في نهاية الرسالة تستدعي ظرف التخفيف "einfach".`, gs: "ظرف تخفيف ودي: einfach" },
  },
  "b7bf1a84-aeac-4c6a-bcc5-87dc21565498": { // Frau Goronsksa
    21: { kw: "davon", ex: `الضمير الظرفي "davon" (=von den zehn Schulen) يشير إلى العدد الكلي المذكور (zehn Schulen) لتفصيل التوزيع (acht davon in Deutschland = ثمانية منها). أما "dabei" (في هذا الصدد) و"daraus" (من ذلك، بمعنى نتيجة) لا يعبران عن التوزيع الجزئي من كل. المحفز النحوي: التفصيل الجزئي من عدد كلي مذكور سابقاً يستدعي "davon".`, gs: "ضمير ظرفي للتوزيع الجزئي: davon" },
    22: { kw: "denen", ex: `جملة نسبية يعود ضمير الوصل فيها على اسم جمع "zehn Schulen"، وحرف الجر "an" قبله يحكم Dativ (an denen = في المدارس التي...)، فضمير الوصل الجمع بحالة الجر "denen". أما "die" حالة الرفع/النصب لا الجر، و"den" ليست صيغة ضمير وصل صحيحة هنا. المحفز النحوي: حرف الجر "an" يحدد Dativ، والاسم المعاد إليه جمع، فالصحيح "denen".`, gs: "ضمير وصل جمع بحالة الجر: denen" },
    23: { kw: "an", ex: `"an fünf Tagen pro Woche" تعبير زمني ثابت (في خمسة أيام بالأسبوع)، وحرف الجر "an" يُستخدم مع أيام محددة (an einem Tag/an Tagen). أما "durch" (من خلال) و"in" لا يناسبان هذا التعبير الزمني الثابت مع "Tagen". المحفز النحوي: التعبير الزمني الثابت مع أيام الأسبوع يستدعي "an".`, gs: "حرف جر زمني ثابت مع أيام: an" },
    24: { kw: "Mittwochs", ex: `"mittwochs" (بصيغة الجمع الظرفية) ظرف تكرار أسبوعي يعني "كل أربعاء"، وهو الصيغة القياسية للتكرار الأسبوعي في الألمانية (montags, dienstags, mittwochs...). أما "Jeder Mittwoch" صيغة اسمية غير مصرّفة ظرفياً هنا، و"Zum Mittwoch" حرف جر لا يعطي معنى التكرار المنتظم. المحفز النحوي: التكرار الأسبوعي المنتظم (لا نحاضر بعد الظهر) يستدعي الصيغة الظرفية القياسية "mittwochs".`, gs: "ظرف تكرار أسبوعي: mittwochs" },
    25: { kw: "jedes Kurses", ex: `"zu Beginn jedes Kurses" تعبير يتطلب حالة الجر (Genitiv) بعد "Beginn" (بداية كل دورة)، والاسم "Kurs" (مذكر) في حالة الجر المفرد يأخذ نهاية "-es": Kurses. أما "jedem Kurs" حالة الجر Dativ (خاطئة هنا)، و"jeden Kurs" حالة النصب Akkusativ. المحفز النحوي: الاسم "Beginn" يتبعه اسم آخر في حالة الملكية (Genitiv)، وهذا يفرض "jedes Kurses".`, gs: "حالة الملكية بعد اسم: Beginn + Genitiv" },
    26: { kw: "dessen", ex: `جملة نسبية بحالة الجر (Genitiv) تصف ملكية ("مساعدته" = مساعدة الاختبار)، وتعود على اسم مذكر مفرد "Einstufungstest". ضمير الوصل بحالة الجر المذكر هو "dessen". أما "der" حالة الرفع لا تعبّر عن الملكية، و"deren" حالة الجر المؤنث/الجمع ولا تناسب اسماً مذكراً مفرداً. المحفز النحوي: الجملة النسبية التي تصف ملكية لاسم مذكر مفرد تستدعي "dessen".`, gs: "ضمير وصل بحالة الملكية (مذكر): dessen" },
    27: { kw: "wenn", ex: `"wenn" أداة ربط شرطية تعني "إذا/عندما" وتصف شرطاً عاماً متكرراً (كلما اجتزت الاختبار تحصل على شهادة). أما "obwohl" (رغم أن) تفيد تضاداً غير موجود هنا، و"wobei" (حيث) ظرفية وصفية لا شرطية. المحفز النحوي: وصف شرط عام لنتيجة (اجتياز الاختبار→شهادة) يستدعي أداة الشرط "wenn".`, gs: "أداة شرطية عامة: wenn" },
    28: { kw: "Ihnen", ex: `"Ihnen" ضمير المخاطب الرسمي بحالة الجر (Dativ) في رسالة رسمية (Sehr geehrte Frau...)، مطابق لصيغة المخاطبة المهذبة المستخدمة طوال الرسالة. أما "Sie" حالة الرفع/النصب، و"Euch" ضمير مخاطبة غير رسمي (جمع المخاطبين العاديين) لا يناسب الأسلوب الرسمي. المحفز النحوي: السياق الرسمي (Sehr geehrte Frau) يستلزم صيغة المخاطبة الرسمية بحرف كبير "Ihnen".`, gs: "ضمير مخاطبة رسمي: Ihnen" },
    29: { kw: "ist", ex: `الفعل "sein" في تركيب المبني للمجهول الحالتي (Zustandspassiv: sein+Partizip II) يصف حالة نتيجة (Halbpension ist eingeschlossen = نصف الإقامة مُدرجة/متضمنة كحالة قائمة)، بخلاف "werden+Partizip II" (Vorgangspassiv) الذي يصف فعلاً جارياً. أما "hat" لا يشكل هذا التركيب، و"wird" يصف عملية جارية لا حالة ثابتة كهذه (الإدراج في السعر حالة قائمة وليست عملية تحدث الآن). المحفز النحوي: وصف حالة قائمة (شيء مُتضمَّن مسبقاً في السعر) يستدعي المبني للمجهول الحالتي "sein+Partizip II".`, gs: "مبني للمجهول حالتي: sein + Partizip II (Zustandspassiv)" },
    30: { kw: "eine Diät halten müssen", ex: `الجملة تبدأ بـ"oder" معطوفة على "vegetarisch essen" (مصدر+فعل)، ويجب أن يحافظ التركيب المعطوف على نفس الترتيب النحوي (فعل الجملة في نهايتها كجملة ثانوية بعد "wenn")، فيصبح "eine Diät halten müssen" (اسم+فعل مصدر+فعل شرطي مصدر في النهاية). أما "müssen eine Diät halten" يضع الفعل الشرطي أولاً وهذا يناسب الجملة الرئيسية لا الثانوية، و"müssen halten eine Diät" ترتيب خاطئ تماماً للمفعول به والفعل. المحفز النحوي: الجملة الثانوية بعد "wenn" تتطلب ترتيب الأفعال في النهاية (Verbletztstellung)، وهذا يحدد ترتيب "eine Diät halten müssen".`, gs: "ترتيب الأفعال في جملة ثانوية: Verbletztstellung" },
  },
  "fa624515-751b-40d3-942f-367ea43c6d15": { // Frau Melchior
    21: { kw: "in dem", ex: `جملة نسبية يعود ضمير الوصل المدمج مع حرف الجر "in dem" (=in welchem Schreiben) على اسم محايد مفرد "Schreiben"، وحرف الجر "in" مع الطلب المذكور فيه (Sie...gebeten haben) يدل على مضمون الرسالة. أما "für das" و"von dem" لا يناسبان تعبير "in einem Schreiben um etwas bitten" (تطلب شيئاً في رسالة). المحفز النحوي: الفعل "bitten" داخل مضمون الرسالة يستدعي حرف الجر "in" مع ضمير الوصل المحايد "dem".`, gs: "ضمير وصل محايد بحرف جر: in dem" },
    22: { kw: "Da", ex: `"Da" في بداية الجملة أداة ربط سببية (بما أن) تصف سبباً لتقديم معلومات مسبقة (بما أن الكتيب لن يجهز إلا بعد أسبوعين). أما "Wann" (متى) أداة استفهام، و"Wenn" (إذا/عندما) أداة شرطية/زمنية لا سببية بهذا الوضوح. المحفز النحوي: تقديم سبب لفعل لاحق (إعطاء معلومات مسبقة) يستدعي "Da" السببية.`, gs: "أداة ربط سببية: Da" },
    23: { kw: "Untergebracht", ex: `"untergebracht sein/werden" تعبير ثابت يعني "يُسكَّن/يُقيم في مكان" (Untergebracht sind Sie im Hotel = ستُقيمون في الفندق)، وهو الفعل المناسب لوصف مكان الإقامة أثناء رحلة. أما "verbracht" (من verbringen: يقضي وقتاً) لا يناسب وصف السكن، و"zugebracht" ليس تعبيراً شائعاً بهذا المعنى. المحفز النحوي: وصف مكان الإقامة يستدعي التعبير الثابت "untergebracht sein".`, gs: "تعبير ثابت للإقامة: untergebracht sein" },
    24: { kw: "sich", ex: `"sich befinden" فعل انعكاسي يعني "يقع/يتواجد" (das Hotel, das sich in der Stadtmitte befindet)، والفاعل هنا "das" (يعود على Hotel، غائب مفرد)، فالضمير الانعكاسي المطابق "sich". أما "man" ضمير عام لا يعود على الفندق، و"Sie" ضمير مخاطب لا يناسب وصف موقع الفندق. المحفز النحوي: الفعل الانعكاسي "sich befinden" مع فاعل غائب (das Hotel) يستدعي الضمير الانعكاسي "sich".`, gs: "فعل انعكاسي مع فاعل غائب: sich befinden" },
    25: { kw: "gezeigt", ex: `"jemandem etwas zeigen" (يُري شخصاً شيئاً)، وفي صيغة المبني للمجهول (werden+Partizip II): "Ihnen...Sehenswürdigkeiten gezeigt werden" (ستُعرض عليكم المعالم). أما "geschaut" (من schauen: ينظر) فعل غير متعدٍ لا يحمل مفعولاً به بهذا الشكل، و"gesehen" (من sehen: يرى) يصف فعل المُشاهد لا فعل من يعرض. المحفز النحوي: المبني للمجهول يصف من يقوم بعرض المعالم للسائحين، وهذا يحدد "zeigen→gezeigt".`, gs: "Partizip II في المبني للمجهول: zeigen → gezeigt" },
    26: { kw: "der", ex: `"ein Besuch der Semper-Oper" تركيب اسمي يتطلب حالة الجر (Genitiv) بعد "Besuch" (زيارة الأوبرا)، والاسم "Semper-Oper" مؤنث، فأداة التعريف في حالة الجر المؤنث "der". أما "die" حالة الرفع/النصب المؤنث لا الجر، و"von" لا يُستخدم هنا مع "Besuch" بنفس الطريقة الرسمية المختصرة. المحفز النحوي: الاسم "Besuch" يتبعه اسم في حالة الملكية (Genitiv)، فالأداة الصحيحة "der" (مؤنث، جر).`, gs: "حالة الملكية بعد اسم: Besuch + Genitiv (مؤنث: der)" },
    27: { kw: "für", ex: `"für seine exotischen Pflanzen berühmt sein" تعبير ثابت (مشهور بسبب/بفضل شيء)، وحرف الجر "für" يدل على سبب الشهرة. أما "mit" (مع) و"wegen" (بسبب، لكن أقل استخداماً في هذا التعبير الثابت تحديداً) لا يشكلان التعبير الصحيح مع "berühmt". المحفز النحوي: صفة "berühmt" في تعبيرها الثابت مع سبب الشهرة تستدعي "für".`, gs: "تعبير ثابت: berühmt für" },
    28: { kw: "steht", ex: `"jemandem zur freien Verfügung stehen" تعبير ثابت يعني "يكون متاحاً/تحت تصرف شخص بحرية" (der 7. Juni steht zu Ihrer freien Verfügung = اليوم السابع متاح لتصرفكم الحر). أما "fällt" (يقع/يسقط) و"liegt" (يقع/يستلقي) لا يشكلان هذا التعبير الثابت. المحفز النحوي: التعبير الثابت "zur Verfügung stehen" يحدد الفعل "stehen".`, gs: "تعبير ثابت: zur Verfügung stehen" },
    29: { kw: "teilnehmen", ex: `"an etwas teilnehmen" فعل مركب منفصل ثابت يعني "يشارك في نشاط" (an einer Fahrt teilnehmen)، وحرف الجر "an" (المذكور سابقاً في الجملة) يؤكد هذا الفعل تحديداً. أما "beteiligen" (يُشرك/يُساهم) يُستخدم عادة بصيغة انعكاسية مختلفة (sich beteiligen an)، و"fahren" (يسافر) لا يترافق مع "an einer Fahrt" بهذا الشكل الزائد. المحفز النحوي: حرف الجر "an" السابق يحدد الفعل المتلازم معه "teilnehmen".`, gs: "فعل ثابت + حرف جر: an etwas teilnehmen" },
    30: { kw: "verschaffen", ex: `"jemandem einen Überblick verschaffen" تعبير ثابت يعني "يمنح/يوفر لشخص نظرة عامة عن شيء" (diese Informationen...einen Überblick verschaffen). أما "vermachen" (يُوصي بشيء لشخص بعد الوفاة) معنى مختلف تماماً، و"schaffen" (يخلق/ينجز) لا يشكل هذا التعبير الثابت مع "Überblick" بنفس الدقة. المحفز النحوي: التعبير الثابت "einen Überblick verschaffen" يحدد الفعل "verschaffen".`, gs: "تعبير ثابت: einen Überblick verschaffen" },
  },
  "cec6ec5c-83ec-461a-b5b2-bb249a1bed74": { // Frau Stein Neu
    21: { kw: "Ihres Vortrags", ex: `"anlässlich" حرف جر يحكم حالة الجر (Genitiv) ويعني "بمناسبة" (بمناسبة محاضرتكم). الاسم "Vortrag" (مذكر) بعد ضمير الملكية "Ihr" في حالة الجر يأخذ نهاية "-s": "Ihres Vortrags". أما "Ihrem Vortrag" حالة الجر Dativ (لا يحكمها "anlässlich")، و"Ihren Vortrag" حالة النصب Akkusativ. المحفز النحوي: حرف الجر "anlässlich" يحكم Genitiv دائماً، فيفرض "Ihres Vortrags".`, gs: "حرف جر يحكم Genitiv: anlässlich" },
    22: { kw: "ob", ex: `"ob" أداة ربط تُدخل سؤالاً غير مباشر بعد فعل الاستفسار "anfragen" (أستفسر عمّا إذا كنتم مستعدين)، وتفيد الشك بين إمكانيتين (موافقة أو رفض). أما "wenn" أداة شرطية/زمنية، و"dass" تُدخل جملة تفسيرية مؤكدة وليس سؤالاً. المحفز النحوي: الفعل "anfragen" لنقل استفسار غير مباشر يتطلب "ob".`, gs: "أداة سؤال غير مباشر: ob (مع anfragen)" },
    23: { kw: "sowohl...als auch", ex: `"sowohl...als auch" أداة ربط مزدوجة (سواء...أو أيضاً) تجمع بين عنصرين دون استبعاد (محاضرات وأيضاً ورشات عمل، أي كلاهما معاً). أما "und...und" ليست أداة ربط مزدوجة قياسية بهذا الشكل، و"zwar...aber" (صحيح أن...لكن) تفيد تضاداً غير مقصود هنا. المحفز النحوي: الجمع بين عنصرين برنامجيين معاً يستدعي "sowohl...als auch".`, gs: "أداة ربط مزدوجة جامعة: sowohl...als auch" },
    24: { kw: "bis", ex: `"von 9 Uhr bis 18 Uhr" تعبير زمني ثابت يحدد فترة زمنية (من...إلى)، وحرف الجر "bis" وحده كافٍ هنا بعد "von" السابقة. أما "bis zu" و"bis vor" يضيفان معنى زائداً (حتى نقطة معينة قبل وقت آخر) لا يناسب التعبير المباشر عن نهاية الفترة الزمنية. المحفز النحوي: التعبير الثابت "von...bis" لتحديد فترة زمنية يستدعي "bis" وحدها.`, gs: "تعبير زمني ثابت: von...bis" },
    25: { kw: "deren", ex: `جملة نسبية بحالة الملكية (Genitiv) تصف "مواضيعها" (مواضيع الخبيرة)، وتعود على اسم مؤنث مفرد "Gesundheitsexpertin". ضمير الوصل بحالة الجر المؤنث للملكية هو "deren". أما "denen" حالة الجر العادية (Dativ، ليست ملكية) وتناسب الجمع لا المفرد المؤنث بهذا المعنى، و"die" حالة الرفع لا تعبّر عن الملكية. المحفز النحوي: وصف ملكية ("مواضيعها") لاسم مؤنث مفرد يستدعي "deren".`, gs: "ضمير وصل بالملكية (مؤنث): deren" },
    26: { kw: "Vortragende", ex: `"Vortragende" صفة مُسمّاة (substantiviertes Adjektiv) تعني "محاضِرة/متحدثة"، وهي المناسبة لوصف دور الشخص في الفعالية (نود ضمكم كمحاضِرة). أما "Vorgetragene" (الشيء المُلقى/المُقدَّم) يصف موضوعاً لا شخصاً، و"Vortrag" (محاضرة، الحدث نفسه) اسم للفعالية لا لصفة الشخص القائم بها. المحفز النحوي: وصف دور الشخص (بصفتها) يستدعي الصفة المُسمّاة الدالة على القائم بالفعل "Vortragende".`, gs: "صفة مُسمّاة للشخص القائم بالفعل: Vortragende" },
    27: { kw: "zu sprechen", ex: `"die Möglichkeit geben, zu + Infinitiv" تركيب ثابت (يمنح فرصة لفعل شيء)، والفعل يتبع بصيغة المصدر مع "zu" بعد "die Möglichkeit geben". أما "geredet haben" صيغة Perfekt غير مناسبة بعد هذا التركيب، و"sprechen" مصدر بدون "zu" لا يتبع هذا التعبير الثابت الذي يتطلب "zu+Infinitiv". المحفز النحوي: التعبير الثابت "die Möglichkeit geben, zu+Infinitiv" يحدد صيغة "zu sprechen".`, gs: "تعبير ثابت + zu-Infinitiv: die Möglichkeit geben, zu..." },
    28: { kw: "zur Verfügung", ex: `"jemandem zur Verfügung stehen" تعبير ثابت (يكون متاحاً لتصرف شخص)، مناسب لوصف توفر الأجهزة التقنية للمحاضِرة. أما "zu Hilfe" (للمساعدة، تعبير مختلف مثل zu Hilfe kommen) و"zum Benutzen" (للاستخدام، ليس تعبيراً ثابتاً بهذا الشكل) لا يناسبان. المحفز النحوي: التعبير الثابت "zur Verfügung stehen" يحدد هذا الاختيار.`, gs: "تعبير ثابت: zur Verfügung stehen" },
    29: { kw: "ein paar Tage", ex: `"ein paar Tage vorher" تعبير زمني بمعنى "قبل أيام قليلة" يصف مدة معقولة لإرسال أوراق العمل مسبقاً للنسخ. أما "eines Tages" (ذات يوم، إشارة لزمن غير محدد في الماضي أو المستقبل البعيد) لا يناسب سياق التحضير القريب، و"für einen Tag" (لمدة يوم واحد) يصف مدة لا نقطة زمنية سابقة. المحفز النحوي: سياق التحضير المسبق لمواد يستدعي تعبير "قبل مدة قصيرة" وهو "ein paar Tage" (فقط، دون "vorher" الزائدة لأنها مذكورة أصلاً في النص).`, gs: "تعبير زمني: ein paar Tage (vorher)" },
    30: { kw: "dabei", ex: `"damit rechnen" تعبير ثابت (يتوقع/يحسب حساباً لشيء)، والضمير الظرفي "dabei" هنا مستخدم بمعنى مختلف قليلاً ("rechnen" مع "dass" اللاحقة لا يحتاج عادة ضميراً ظرفياً منفصلاً، لكن "wir rechnen dabei/damit" كلاهما مستخدمان في الألمانية بمرونة كإشارة تمهيدية لجملة dass اللاحقة، مع تفضيل "damit" اصطلاحياً لكن "dabei" مقبول في سياقات معينة كإشارة عامة للحدث المتوقع). أما "dafür"/"dazu" لا يرتبطان بفعل "rechnen mit" الذي يتطلب "mit" أصلاً (والضمير الظرفي المطابق لـ"mit" هو "damit" وليس "dafür/dazu" المرتبطين بـ"für/zu"). المحفز النحوي: الفعل الثابت "rechnen mit etwas" يحدد الضمير الظرفي المطابق لحرف الجر "mit".`, gs: "فعل ثابت + ضمير ظرفي: rechnen mit → dabei/damit" },
  },
  "4d84966a-dc16-477d-898e-803226e91756": { // Frau Szabo Original
    21: { kw: "an", ex: `"Interesse an etwas" تعبير ثابت يعني "اهتمام بشيء"، وحرف الجر "an" هو المرافق الثابت لهذا الاسم. أما "bei" و"in" لا يشكلان هذا التعبير الثابت مع "Interesse". المحفز النحوي: الاسم "Interesse" في تعبيره الثابت "Interesse an" يحدد "an".`, gs: "تلازم لفظي: Interesse an" },
    22: { kw: "in Höhe", ex: `"eine Anzahlung in Höhe von..." تعبير مالي رسمي ثابت (بمقدار/بقيمة مبلغ محدد)، شائع في المراسلات الرسمية لتحديد مبلغ مالي. أما "in Betrag" و"in Summe" ليسا تعبيرين ثابتين قياسيين بهذا الشكل الرسمي. المحفز النحوي: التعبير المالي الرسمي الثابت "in Höhe von" هو الصيغة المعتمدة لتحديد مبلغ.`, gs: "تعبير مالي رسمي ثابت: in Höhe von" },
    23: { kw: "Für", ex: `"für eine bessere Einschätzung" تعبير يصف الغرض (من أجل تقييم أفضل)، وحرف الجر "für" يدل على الهدف من إرفاق الاختبار. أما "Zur" (لأجل، مدمجة zu+der) قد تعمل أيضاً لكنها أقل ملاءمة أسلوبياً هنا مقارنة بالخيار الصحيح المحدد "Für"، و"Zwecks" (بغرض) رسمية جداً وتتطلب بنية مختلفة قليلاً. المحفز النحوي: الغرض من إرفاق الاختبار (تقييم أفضل) يستدعي حرف الجر الغرضي "für".`, gs: "حرف جر غرضي: für" },
    24: { kw: "anschließen", ex: `الجملة "Ein mündlicher Test wird sich...anschließen" في المستقبل (wird+Infinitiv)، والفعل الانعكاسي "sich anschließen" (يلحق/يتبع) يبقى بصيغة المصدر بعد الفعل المساعد "wird". أما "angeschlossen" صيغة Partizip II لا تناسب تركيب المستقبل wird+Infinitiv، و"schließen an" ترتيب خاطئ (البادئة المنفصلة يجب أن تلتصق كوحدة في صيغة المصدر: anschließen). المحفز النحوي: الفعل المساعد "wird" في صيغة المستقبل يتطلب الفعل التالي بصيغة المصدر الكاملة "anschließen".`, gs: "فعل انعكاسي منفصل بصيغة المصدر بعد wird: sich anschließen" },
    25: { kw: "bezüglich", ex: `"bezüglich" حرف جر رسمي يعني "بخصوص/فيما يتعلق بـ" (استبيان بخصوص اهتماماتكم)، شائع في المراسلات الرسمية. أما "anlässlich" (بمناسبة) تصف دافعاً/مناسبة لا موضوعاً، و"mittels" (بواسطة) تصف أداة/وسيلة لا موضوعاً. المحفز النحوي: تقديم استبيان عن موضوع محدد يستدعي حرف الجر الرسمي "bezüglich".`, gs: "حرف جر رسمي للموضوع: bezüglich" },
    26: { kw: "wie", ex: `"so...wie möglich" تركيب مقارنة ثابت (بأقصى قدر ممكن)، والصفة "angenehm" في صيغتها الأساسية تتطلب "wie" بعد "so". أما "als" تُستخدم بعد صيغة المقارنة (Komparativ) لا بعد "so"+صفة أساسية، و"wenn" لا معنى مقارن لها. المحفز النحوي: التركيب "so+صفة+wie möglich" يحدد "wie" حصراً.`, gs: "تركيب مقارنة ثابت: so...wie möglich" },
    27: { kw: "einer", ex: `التعداد بين ثلاثة خيارات إقامة يتطلب أداة تنكير مفردة تتفق مع الاسم المؤنث "Privatunterkunft" في حالة الجر (Dativ بعد "zwischen"): "einer". أما "ein" حالة الرفع/النصب المحايد لا تناسب المؤنث، و"einem" حالة الجر لكن للمذكر/المحايد لا المؤنث. المحفز النحوي: حرف الجر "zwischen" يحكم Dativ، والاسم "Privatunterkunft" مؤنث، فأداة التنكير الصحيحة "einer".`, gs: "أداة تنكير مؤنثة بحالة الجر: einer" },
    28: { kw: "Sobald", ex: `"Sobald" أداة ربط زمنية تعني "بمجرد أن" وتصف تتابعاً فورياً بين حدثين (بمجرد وصول التسجيل، تحصلون على تأكيد). أما "Sofort" (فوراً) ظرف مستقل وليس أداة ربط تُدخل جملة ثانوية، و"Sooft" (كلما) تفيد التكرار المتعدد لا الحدوث لمرة واحدة. المحفز النحوي: وصف تتابع فوري لمرة واحدة (استلام→تأكيد) يستدعي "Sobald".`, gs: "أداة ربط زمنية فورية: Sobald" },
    29: { kw: "damit", ex: `"damit" أداة ربط غرضية (لكي) تُستخدم عندما يختلف فاعل الجملتين (نحن نرسل الخريطة، أنتم تجدون الطريق - فاعلان مختلفان)، وهذا يفرض "damit" بدلاً من "um...zu". أما "dafür" ضمير ظرفي لا يُدخل جملة غرضية بهذا الشكل، و"dazu" أيضاً ضمير ظرفي لا أداة ربط غرضية. المحفز النحوي: اختلاف الفاعل بين الجملتين (نحن/أنتم) يستدعي "damit" وليس "um...zu".`, gs: "أداة ربط غرضية بفاعلين مختلفين: damit" },
    30: { kw: "Bei", ex: `"bei weiteren Fragen" تعبير ثابت رسمي (في حال وجود أسئلة إضافية) شائع في ختام الرسائل الرسمية للدلالة على الاستعداد للمساعدة. أما "Für" و"Zu" لا يشكلان هذا التعبير الثابت الرسمي الشائع بنفس الطريقة. المحفز النحوي: التعبير الرسمي الختامي الثابت "bei weiteren Fragen" يحدد "Bei".`, gs: "تعبير ختامي رسمي ثابت: bei weiteren Fragen" },
  },
  "1edcc63d-f03f-4a20-af93-23712b949f35": { // Frau Szabo معدل
    21: { kw: "anbei", ex: `"anbei" ظرف رسمي يعني "مرفق طيه" ويُستخدم في بداية جملة لإرفاق مستند (anbei erhalten Sie... = مرفق لكم...). أما "dabei" (في هذا الصدد) و"vorbei" (بجانب/مرت) لا يحملان معنى الإرفاق الرسمي. المحفز النحوي: سياق إرفاق مستند رسمي (استمارة التسجيل) يستدعي الظرف الرسمي الثابت "anbei".`, gs: "ظرف رسمي للإرفاق: anbei" },
    22: { kw: "in Höhe", ex: `"eine Anzahlung in Höhe von..." تعبير مالي رسمي ثابت شائع في المراسلات الرسمية. أما "in Betrag" و"in Summe" ليسا تعبيرين ثابتين قياسيين. المحفز النحوي: التعبير المالي الرسمي الثابت "in Höhe von" هو المعتمد.`, gs: "تعبير مالي رسمي ثابت: in Höhe von" },
    23: { kw: "zur", ex: `"zur genaueren Einschätzung" (zu+der، مدمجة) تعبير غرضي يعني "من أجل تقييم أدق"، وحرف الجر "zu" شائع مع الصفة الغرضية هنا. أما "für" أقل شيوعاً في هذا التعبير الرسمي المحدد، و"zweck" (بحرف صغير خطأ إملائي، والصحيح Zwecks كحرف جر مستقل) لا يناسب البنية هنا. المحفز النحوي: التعبير الرسمي "zur besseren/genaueren Einschätzung" يحدد "zur".`, gs: "حرف جر غرضي رسمي: zur" },
    24: { kw: "stattfinden", ex: `"stattfinden" فعل مركب منفصل يعني "يُقام/يحدث" (der Test wird...stattfinden = سيُقام الاختبار)، مناسب لوصف إقامة اختبار في المستقبل (wird+Infinitiv). أما "durchführen" (يُجري/يُنفّذ) يتطلب فاعلاً بشرياً يقوم بالفعل (وهنا الفاعل هو الاختبار نفسه، فيُستخدم عادة بصيغة المبني للمجهول لا "durchführen" المباشرة بهذا الشكل)، و"veranstalten" (ينظم فعالية) يستخدم عادة لفعاليات أكبر وليس اختباراً فردياً بهذه الطريقة. المحفز النحوي: وصف إقامة اختبار (بدون فاعل منفّذ صريح) يستدعي الفعل غير المتعدي "stattfinden".`, gs: "فعل غير متعدٍ للإقامة/الحدوث: stattfinden" },
    25: { kw: "bezüglich", ex: `"bezüglich" حرف جر رسمي يعني "بخصوص" (استبيان بخصوص اهتماماتكم). أما "anlässlich" (بمناسبة) دافع لا موضوع، و"mittels" (بواسطة) أداة لا موضوع. المحفز النحوي: تقديم استبيان عن موضوع يستدعي "bezüglich".`, gs: "حرف جر رسمي للموضوع: bezüglich" },
    26: { kw: "möglichst", ex: `"möglichst angenehm" ظرف تفضيل مطلق يعني "بأقصى قدر ممكن من الراحة"، وهو الصيغة الظرفية الثابتة الملازمة لصفة تليها مباشرة (möglichst+صفة). أما "möglich" (ممكن) صفة عادية لا ظرف تفضيل، و"möglicherweise" (ربما/من المحتمل) تفيد الاحتمال لا التفضيل الأقصى. المحفز النحوي: وصف أقصى درجة من صفة (الراحة) مباشرة قبل الصفة يستدعي الظرف "möglichst".`, gs: "ظرف تفضيل مطلق قبل صفة: möglichst" },
    27: { kw: "einer", ex: `التعداد بين خيارات إقامة يتطلب أداة تنكير مؤنثة بحالة الجر (Dativ بعد zwischen) تتفق مع "Privatunterkunft": "einer". أما "ein" و"einem" لا يطابقان الجنس المؤنث بحالة الجر. المحفز النحوي: حرف الجر "zwischen"+اسم مؤنث يحددان "einer".`, gs: "أداة تنكير مؤنثة بحالة الجر: einer" },
    28: { kw: "Sobald", ex: `"Sobald" أداة ربط زمنية (بمجرد أن) تصف تتابعاً فورياً (بمجرد الوصول، تحصلون على تأكيد). أما "Sofort" ظرف مستقل لا أداة ربط، و"Sooft" تفيد التكرار المتعدد. المحفز النحوي: تتابع فوري لمرة واحدة يستدعي "Sobald".`, gs: "أداة ربط زمنية فورية: Sobald" },
    29: { kw: "damit", ex: `"damit" أداة ربط غرضية تُستخدم عند اختلاف فاعل الجملتين (نحن نرسل الخريطة، أنتم تجدون الطريق). أما "dafür"/"dazu" ضميران ظرفيان لا أداتا ربط غرضية. المحفز النحوي: اختلاف الفاعل يستدعي "damit".`, gs: "أداة ربط غرضية بفاعلين مختلفين: damit" },
    30: { kw: "Bei", ex: `"bei weiteren Fragen" تعبير ختامي رسمي ثابت (في حال وجود أسئلة إضافية). أما "Für" و"Als" لا يشكلان هذا التعبير الثابت. المحفز النحوي: التعبير الختامي الرسمي الثابت يحدد "Bei".`, gs: "تعبير ختامي رسمي ثابت: bei weiteren Fragen" },
  },
  "a7fea463-902e-488e-8fee-2c5c391227dd": { // HausbewohnerInnen
    21: { kw: "Dafür", ex: `"Dafür" ضمير ظرفي في بداية الجملة يشير إلى الهدف المذكور سابقاً (تجهيز المبنى للشتاء)، بمعنى "من أجل ذلك" (لأجل هذا الهدف لا تزال هناك استعدادات ضرورية). أما "Damit" (لكي) أداة ربط غرضية تحتاج جملة ثانوية كاملة تليها وليست ظرفاً مستقلاً هنا، و"So" (هكذا) لا يحمل نفس معنى الإشارة الغرضية المحددة. المحفز النحوي: الإشارة لهدف سابق (التجهيز الشتوي) في بداية جملة جديدة تستدعي الضمير الظرفي "Dafür".`, gs: "ضمير ظرفي غرضي: dafür" },
    22: { kw: "werden", ex: `الجملة بصيغة المبني للمجهول (werden+Partizip II: durchgeführt) تصف عملية ستُنفَّذ (أعمال الصيانة ستُجرى)، والفاعل الحقيقي (من يقوم بالعمل) غير مذكور. أما "sind" تشكل Zustandspassiv (حالة نتيجة) وليس عملية مستقبلية مخطط لها، و"können" فعل شرطي يغيّر المعنى إلى إمكانية لا تخطيطاً مؤكداً. المحفز النحوي: وصف عملية مستقبلية مخططة (أعمال الصيانة) بالمبني للمجهول يستدعي "werden+Partizip II".`, gs: "مبني للمجهول لعملية مستقبلية: werden + Partizip II" },
    23: { kw: "bis", ex: `"bis zu diesem Datum" تعبير زمني يعني "حتى هذا التاريخ" (كموعد نهائي لإزالة الأغراض). أما "bei" (عند) يدل على نقطة زمنية محددة لا مهلة زمنية، و"vor" (قبل) يفيد سبق التاريخ لكن دون تحديد المهلة الممتدة بنفس الوضوح. المحفز النحوي: تحديد موعد نهائي كمهلة زمنية يستدعي حرف الجر "bis".`, gs: "حرف جر زمني للموعد النهائي: bis" },
    24: { kw: "behoben", ex: `الجملة بصيغة المبني للمجهول (werden müssen+Partizip II: behoben werden müssen = يجب أن تُصلَح)، والفعل "beheben" (يُصلح ضرراً) في صيغة Partizip II هي "behoben". أما "beheben" مصدر غير مصرّف، و"behebt" صيغة مضارع مصرّفة لا تناسب تركيب المبني للمجهول مع الفعل الشرطي. المحفز النحوي: تركيب "werden+Partizip II+müssen" يفرض صيغة اسم المفعول "behoben".`, gs: "Partizip II في مبني للمجهول مع فعل شرطي: behoben werden müssen" },
    25: { kw: "um", ex: `"um...zu+Infinitiv" تركيب غرضي (من أجل أن) يصف هدف قدوم عمال الزجاج (ليركّبوا نوافذ جديدة)، وفاعل الجملتين نفسه (العمال). أما "dass" لا تُدخل جملة غرضية بهذا الشكل المباشر، و"für" لا تُدخل جملة كاملة. المحفز النحوي: تطابق الفاعل (العمال) بين المجيء والتركيب يستدعي "um...zu".`, gs: "تركيب غرضي بفاعل مشترك: um...zu" },
    26: { kw: "ermöglichen", ex: `"den Zugang ermöglichen" تعبير ثابت يعني "يُتيح/يُسهّل الوصول" (نطلب منكم إتاحة الوصول إلى مخازنكم للعمال). أما "verhindern" (يمنع) معنى معاكس تماماً، و"vergessen" (ينسى) لا معنى له مع "Zugang". المحفز النحوي: طلب تسهيل عمل العمال (لا إعاقتهم) يستدعي "ermöglichen".`, gs: "فعل ثابت + مفعول به: Zugang ermöglichen" },
    27: { kw: "letzter", ex: `"in letzter Zeit" تعبير زمني ثابت يعني "في الآونة الأخيرة" (ازدادت الشكاوى في الآونة الأخيرة)، وحالة الجر بعد "in" بدون أداة تعريف تتطلب تصريفاً قوياً (starke Deklination) للصفة المؤنثة: "-er" → "letzter". أما "einiger" (بعض) لا يعطي معنى "الأخيرة" الزمني المحدد، و"letzte" (نهاية -e) تناسب حالة الرفع/النصب لا الجر بدون أداة. المحفز النحوي: التعبير الثابت "in letzter Zeit" يستخدم تصريفاً قوياً بنهاية "-er" في حالة الجر المؤنث بدون أداة.`, gs: "تصريف قوي بدون أداة في حالة الجر: letzter Zeit" },
    28: { kw: "dass", ex: `"darauf achten, dass..." تعبير ثابت (يحرص على أن...) وأداة الربط "dass" تُدخل الجملة التفسيرية لموضوع الحرص (ألا يشعر الجيران بالإزعاج). أما "weswegen" (الذي بسببه) أداة ربط نسبية غير مناسبة هنا، و"weil" (لأن) سببية لا تناسب تركيب "achten darauf, dass". المحفز النحوي: التعبير الثابت "darauf achten, dass" يحدد "dass" حصراً.`, gs: "تعبير ثابت: darauf achten, dass" },
    29: { kw: "Bällen", ex: `"mit etwas spielen" (يلعب بشيء) يحكم حالة الجر (Dativ) بعد "mit"، والاسم "Ball" (كرة) في حالة الجر الجمع يأخذ نهاية "-en": "Bällen" (مع تحول الصوت إلى Umlaut في صيغة الجمع الأصلية Bälle، ثم إضافة -n في حالة الجر الجمع). أما "Bälle" حالة الرفع/النصب الجمع بدون -n، و"Ballen" (كومة/حزمة، اسم مختلف تماماً وليس جمع Ball). المحفز النحوي: حرف الجر "mit" يحكم Dativ، والجمع في حالة الجر يأخذ "-n" إلزامياً، فالصحيح "Bällen".`, gs: "جمع في حالة الجر بعد mit: Bällen" },
    30: { kw: "freundlichen", ex: `"mit freundlichen Grüßen" تعبير ختامي ثابت للمراسلات، حيث الصفة "freundlich" تصف الاسم الجمع "Grüße" بعد حرف الجر "mit" (Dativ)، فتُصرَّف بنهاية "-en" (تصريف قوي جمع في حالة الجر بدون أداة تعريف). أما "freundliche" (نهاية -e) حالة الرفع/النصب الجمع لا الجر، و"freundlichem" نهاية مفرد لا تناسب الجمع "Grüße". المحفز النحوي: حرف الجر "mit" يحكم Dativ، والصفة قبل اسم جمع بدون أداة تعريف تأخذ نهاية "-en" في حالة الجر.`, gs: "صفة جمع بحالة الجر بدون أداة: freundlichen Grüßen" },
  },
  "123009f3-6299-4036-a571-522132e85c02": { // Herr Dr. Dobromil
    21: { kw: "allergrößtem", ex: `"mit größtem Interesse" تعبير ثابت (باهتمام بالغ) يصف طريقة القراءة، وحرف الجر "mit" يحكم Dativ، والصفة (في صيغة تفضيل مطلق مع بادئة تعزيز aller-) في حالة الجر المحايد بدون أداة تعريف تأخذ نهاية "-em": "allergrößtem". أما "allergrößte" (نهاية -e) حالة الرفع/النصب، و"allergrößten" (نهاية -en) لا تطابق حالة الجر المحايد بدون أداة بنفس الدقة. المحفز النحوي: حرف الجر "mit" يحكم Dativ، والاسم "Interesse" محايد، فالصفة تأخذ نهاية "-em" في هذه الحالة بدون أداة.`, gs: "صفة تفضيل مطلق بحالة الجر المحايد بدون أداة: allergrößtem" },
    22: { kw: "in dem", ex: `جملة نسبية يعود ضمير الوصل المدمج "in dem" (=in welchem Stellenangebot) على اسم محايد مفرد "Stellenangebot"، وحرف الجر "in" يدل على مضمون الإعلان (الذي تبحثون فيه عن موظفة). أما "auf dem" و"an dem" لا يناسبان تعبير "in einem Angebot suchen" (تبحث في إعلان). المحفز النحوي: مضمون الإعلان (البحث داخله) يستدعي حرف الجر "in" مع ضمير الوصل المحايد.`, gs: "ضمير وصل محايد بحرف جر: in dem" },
    23: { kw: "Ihren", ex: `"wie dem Ihren" مقارنة بديلة تشير إلى "متجركم" (مثل متجركم)، حيث الاسم المحذوف ضمنياً "Geschäft" (محايد) في حالة النصب (Akkusativ، مفعول به لفعل "übernehmen" لاحقاً)، فضمير الملكية "Ihr" في حالة النصب المحايد لا يتغير عن الرفع: "Ihren"... انتظر، دعنا نُدقق: الأصل "wie dem Ihren" - "dem" أداة تعريف محايد بحالة الجر (بعد wie بمعنى "مثل ذلك الذي")، وضمير الملكية بعدها "Ihren" لا يتطابق مع "dem" في نفس الحالة عادة إلا كصفة مُسمّاة بعد أداة تعريف (تصريف ضعيف). التصريف الضعيف بعد "dem" (Dativ محايد) يأخذ نهاية "-en": "Ihren" (بصفته اسماً مُسمّى من ضمير الملكية). أما "Ihrem" (نهاية -em) يناسب تصريفاً قوياً بدون أداة، و"Ihres" (نهاية -es، حالة الجر) لا تناسب حالة الجر Dativ هنا بعد "dem". المحفز النحوي: أداة التعريف "dem" (Dativ محايد) قبل ضمير الملكية المُسمّى تفرض التصريف الضعيف بنهاية "-en": "Ihren".`, gs: "تصريف ضعيف لضمير ملكية مُسمّى بعد أداة تعريف: dem Ihren" },
    24: { kw: "zu können", ex: `"es reizt mich, etwas zu übernehmen" + فعل شرطي معدِّل "können" يتطلب صيغة "zu+Infinitiv" الكاملة مع الفعل الشرطي أيضاً بصيغة المصدر متبوعاً بـ"zu" (تركيب فعلين مصدريين متتاليين: übernehmen zu können). أما "können" وحدها (بدون zu) لا تكتمل صيغة المصدر المطلوبة بعد "es reizt mich"، و"könnte" صيغة مصرّفة لا تناسب تركيب المصدر. المحفز النحوي: التعبير "es reizt mich, zu+Infinitiv" مع فعل شرطي مساعد يتطلب صيغة "Infinitiv+zu können" في نهاية سلسلة الأفعال.`, gs: "تركيب مصدر مزدوج: übernehmen zu können" },
    25: { kw: "bei", ex: `"eine Lehre bei einer Firma" تعبير ثابت (تدريب مهني لدى شركة)، وحرف الجر "bei" يدل على جهة التدريب. أما "an" و"mit" لا يشكلان هذا التعبير الثابت مع "Lehre" بهذا المعنى (التدريب لدى جهة عمل). المحفز النحوي: التعبير الثابت "eine Lehre bei jmd./einer Firma" يحدد "bei".`, gs: "تلازم لفظي: eine Lehre bei" },
    26: { kw: "ein Jahr lang", ex: `"ein Jahr lang" تعبير زمني يعني "لمدة عام كامل" ويصف مدة زمنية محددة من العمل بعد التدريب (عملت لمدة عام). أما "durch ein Jahr" ليس تعبيراً ألمانياً قياسياً بهذا الشكل، و"seit einem Jahr" (منذ عام) يصف نقطة بداية مستمرة حتى الحاضر لا مدة منتهية في الماضي (السياق هنا: "arbeitete" ماضٍ منتهٍ، ثم "danach schrieb ich mich ein" - أي أن العمل انتهى، وليس مستمراً حتى الآن). المحفز النحوي: وصف مدة عمل منتهية في الماضي (وليست مستمرة حتى الآن) يستدعي تعبير المدة المحددة "ein Jahr lang" لا "seit".`, gs: "تعبير مدة زمنية منتهية: ein Jahr lang" },
    27: { kw: "entdeckte", ex: `"seine Liebe zu etwas entdecken" تعبير ثابت يعني "يكتشف شغفه بشيء" (اكتشفتُ حبي للأثاث العتيق)، مناسب لوصف اكتشاف اهتمام جديد أثناء الدراسة. أما "erfand" (من erfinden: يخترع) لا يناسب اكتشاف مشاعر داخلية موجودة أصلاً، و"merkte" (لاحظ) أضعف دلالياً من "اكتشاف شغف" عميق. المحفز النحوي: وصف اكتشاف شغف/حب داخلي يستدعي الفعل الثابت "entdecken" في تعبير "seine Liebe entdecken".`, gs: "تعبير ثابت: seine Liebe zu etwas entdecken" },
    28: { kw: "was", ex: `"was...angeht" تعبير ثابت يعني "فيما يتعلق بـ/فيما يخص" (فيما يتعلق بأنماط الأثاث)، وهو تركيب شائع جداً في الألمانية يُستخدم فيه ضمير الوصل غير المحدد "was" (لا "das" الذي يشير لاسم محدد سابق، ولا "welches" الذي هو أقرب لضمير وصل عادي وليس جزءاً من هذا التعبير الثابت). المحفز النحوي: التعبير الاصطلاحي الثابت "was...angeht" (فيما يخص) يحدد "was" حصراً بغض النظر عن الاسم اللاحق.`, gs: "تعبير ثابت: was...angeht" },
    29: { kw: "sowohl ... als auch", ex: `"sowohl in Nordeuropa als auch in Südeuropa" أداة ربط مزدوجة تجمع منطقتين معاً دون استبعاد (المعرفة تشمل كلا المنطقتين). أما "teils...teils" (جزئياً...جزئياً) تفيد التوزيع الجزئي غير المكتمل، و"weder...noch" (لا...ولا) نفي مزدوج يستبعد كليهما، معنى معاكس. المحفز النحوي: الجمع الكامل بين منطقتين في وصف المعرفة الشاملة يستدعي "sowohl...als auch".`, gs: "أداة ربط مزدوجة جامعة: sowohl...als auch" },
    30: { kw: "auf Ihre Anzeige zu antworten", ex: `الجملة "ich habe mich entschlossen, zu + Infinitiv" (قررتُ أن...) تركيب ثابت يتطلب صيغة "zu+Infinitiv" مع الفعل "antworten" (يرد على شيء + auf+Akkusativ: auf Ihre Anzeige). الترتيب الصحيح: [المفعول به+حرف الجر] ثم [zu+الفعل] في نهاية الجملة الثانوية: "auf Ihre Anzeige zu antworten". أما "auf Ihre Anzeige antworten" (بدون zu) لا يكتمل تركيب "sich entschließen, zu+Infinitiv"، و"um auf Ihre Anzeige zu antworten" تضيف "um" الغرضية الزائدة وغير المطلوبة هنا (الفعل "sich entschließen" يتبعه zu+Infinitiv مباشرة دون um). المحفز النحوي: التعبير الثابت "sich entschließen, zu+Infinitiv" يحدد صيغة "zu antworten" دون "um" الزائدة.`, gs: "تعبير ثابت + zu-Infinitiv: sich entschließen, zu..." },
  },
};

