const passageTranslations = {
  "963db4db-8d1b-4e80-8c5c-f49315b93852": "عزيزتي عائلة غايسلر أو ديبولد،\n\nشكراً جزيلاً على ردكم على طلبي كمربية أطفال (Au-pair). شكراً أيضاً على صور الأطفال. أنا متحمسة جداً وأتطلع بشغف للتعرف على عائلتكم في سبتمبر!\n\nفي يونيو سأنهي دراستي المدرسية وأريد أيضاً تحسين لغتي الألمانية قليلاً. لذلك سألتحق في الصيف بدورة لغوية في مدرسة صيفية في وطني. بعدها سأسافر مع عائلتي لثلاثة أسابيع في عطلة على البحر. لدي سؤال لكم. تكتبون أنكم تخططون لعطلة تزلج في عطلة عيد الميلاد يمكنني المشاركة فيها إذا أردت. لكن ليس لدي زلاجات وملابس تزلج. هل يمكنني استعارة هذه الأشياء من أي شخص؟ في وطني لن أحتاجها مرة أخرى تقريباً. لكنني منفتحة دائماً على تجارب جديدة وأود تجربة التزلج مرة واحدة.\n\nشكراً لأنكم ستأتون لاصطحابي من المطار. لقد حجزت رحلتي إلى فرانكفورت بالفعل. في 2 سبتمبر سأصل إلى فرانكفورت مبكراً جداً، تحديداً الساعة 5:15. أقترح أن نلتقي فقط حوالي الساعة 7:30 في مقهى. ربما أتأخر أو يجب أن أنتظر أمتعتي لفترة أطول. حينها لن يتوجب عليكم الحضور مبكراً جداً.\n\nيرجى الكتابة لي إذا أردتم معرفة المزيد عني! سأرسل بعض الصور مع الرسالة حتى يرى الأطفال المزيد قليلاً عني.\n\nتحياتي\nآسيا",
  "6ccc22ad-36c9-426c-8c47-e9c0b8231635": "مرحباً فرديناند،\n\nلم أتواصل معك منذ فترة طويلة - يؤسفني ذلك حقاً! كان لدي ضغط كبير في الأشهر الماضية، لأنني الآن أدرس وأعمل بجانب ذلك من أجل دفع الإيجار وكل شيء آخر. لحسن الحظ عملي الإضافي ممتع على الأقل. لا أعرف كيف كنت سأتحمل ذلك لولاه. ربما أخبرتك من قبل أنني أساعد مساءً وفي عطلة نهاية الأسبوع في مطبخ حانة. الأمر متعب جداً أحياناً، لكن من ناحية أخرى هناك دائماً نشاط، لا يصبح الأمر مملاً، وزملائي لطيفون جداً. هل تتذكر أيامنا في المدرسة الابتدائية؟ في الثامنة من عمري أردت بشدة أن أصبح نادلة، لأن المرء يحصل على إكرامية هناك. حسناً، الآن انتهى بي المطاف في المطبخ، قريب لكن ليس تماماً ;) ماذا عن تدريبك المهني؟ إذا لم أكن مخطئة، ستنتهي منه خلال نصف عام، أليس كذلك؟ هذا ليس وقتاً طويلاً بعد الآن! بالمناسبة، التقيت مؤخراً بتينا وكيفن بالقرب من الجامعة - كانا زوجين منذ كنا في المدرسة، والآن تريد الزواج فعلاً! ما هي خططك لعطلات نهاية الأسبوع القادمة؟ يمكننا ربما أن نلتقي مرة أخرى ونتحدث بهدوء - هل لديك رغبة في ذلك؟ في شارعي افتتح مقهى صغير لطيف منذ شهر، لديهم ليس فقط كعكاً لذيذاً جداً، بل أيضاً بعض الأطباق الصغيرة بأسعار معقولة حقاً. هل سيكون هذا شيئاً يناسبك؟ راسليني ببساطة إذا أردت، سأكون سعيدة.\n\nتحياتي،\nنادين",
  "df4ef1c3-270a-4e89-8f58-90b11284cc78": "مرحباً فرديناند،\n\nلم أتواصل معك منذ فترة طويلة - يؤسفني ذلك حقاً! كان لدي ضغط كبير في الأشهر الماضية، لأنني الآن أدرس وأعمل بجانب ذلك من أجل دفع الإيجار وكل شيء آخر. لحسن الحظ عملي الإضافي ممتع على الأقل. لا أعرف كيف كنت سأتحمل ذلك لولاه. ربما أخبرتك من قبل أنني أساعد مساءً وفي عطلة نهاية الأسبوع في مطبخ حانة. الأمر متعب جداً أحياناً، لكن من ناحية أخرى هناك دائماً نشاط، لا يصبح الأمر مملاً، وزملائي لطيفون جداً. هل تتذكر أيامنا في المدرسة الابتدائية؟ في الثامنة من عمري أردت بشدة أن أصبح نادلة، لأن المرء يحصل على إكرامية هناك. حسناً، الآن انتهى بي المطاف في المطبخ. ماذا عن تدريبك المهني؟ إذا لم أكن مخطئة، ستنتهي منه خلال نصف عام. بالمناسبة، التقيت مؤخراً بتينا وكيفن - كانا زوجين منذ كنا في المدرسة، والآن تريد الزواج فعلاً! ما هي خططك لعطلات نهاية الأسبوع القادمة؟ يمكننا ربما أن نلتقي مرة أخرى - هل لديك رغبة في ذلك؟ في شارعي افتتح مقهى صغير لطيف منذ شهر، لديهم كعك لذيذ جداً وأيضاً بعض الأطباق الصغيرة بأسعار معقولة. هل سيكون هذا ببساطة شيئاً يناسبك؟ راسليني إذا أردت.\n\nتحياتي،\nنادين",
  "b7bf1a84-aeac-4c6a-bcc5-87dc21565498": "السيدة الفاضلة غورونسكا المحترمة،\n\nشكراً جزيلاً على استفساركم بتاريخ 12 سبتمبر بخصوص برامجنا اللغوية في ألمانيا والنمسا. تدير مؤسستنا ما مجموعه عشر مدارس، ثمانية منها في ألمانيا واثنتان في النمسا، حيث يمكنكم دون استثناء تحسين لغتكم الألمانية والمشاركة في برنامج ثقافي وترفيهي متميز.\n\nيُقام التدريس اللغوي عادة في خمسة أيام أسبوعياً، من الساعة 9 إلى 13 ومن 15 إلى 17. كل أربعاء لا يوجد تدريس بعد الظهر. يشمل عرض الدورات جميع المستويات. المدة الدنيا للدورة أسبوعان، لكن يمكنكم البقاء أربعة أو ستة أو ثمانية أسابيع أيضاً. في بداية كل دورة يُجرى اختبار تحديد مستوى، بمساعدته نكتشف الدورة المناسبة لكم. بعد انتهاء إقامتكم تحصلون على شهادة مشاركة.\n\nبالطبع يمكنكم عندنا اجتياز اختبارات في جميع المستويات من A1 إلى C1، وإذا اجتزتم الاختبار تحصلون على شهادة معترف بها دولياً. فيما يتعلق ببرنامجنا الثقافي والترفيهي، هناك خيارات متنوعة تُقدَّم لكم في الموقع. تشمل رحلات إلى المناطق المجاورة، وزيارات للمتاحف والمسارح والمزيد.\n\nفيما يخص المبيت في موقع الدورة، يمكنكم الاختيار بين الإقامة لدى عائلة مضيفة أو في فنادق بسيطة. سعر الإقامة يشمل نصف الإقامة، أي الإفطار والغداء. يرجى إبلاغنا إذا كنتم تستبعدون أطعمة معينة، مثلاً إذا كنتم نباتيين أو يجب عليكم اتباع حمية غذائية. لمزيد من التفاصيل يرجى الرجوع للكتالوج المرفق. لأي استفسارات إضافية نحن هنا لخدمتكم بكل سرور.\n\nمع خالص التحيات\nناتالي شبنغلر",
  "fa624515-751b-40d3-942f-367ea43c6d15": "السيدة ميلشيور المحترمة،\n\nشكراً جزيلاً على رسالتكم من يوم الثلاثاء الماضي، التي طلبتم فيها معلومات أدق عن رحلة درسدن المخطط لها في يونيو القادم. بما أن كتيب برنامجنا لن يجهز إلا بعد أسبوعين، أقدم لكم بعض المعلومات المسبقة.\n\nستُقام الرحلة من 3 إلى 8 يونيو. ستتم الرحلة بالقطار. ستُقيمون في فندق كورونا الواقع في وسط المدينة. ستكون لديكم غرف مفردة أو مزدوجة مع حمام. سعر الرحلة 650 يورو للغرفة المزدوجة و950 يورو للغرفة المفردة، مع الإفطار في كلتا الحالتين.\n\nيبدأ البرنامج الفعلي للرحلة في 4 يونيو بجولة في المدينة، ستُعرض خلالها عليكم أهم المعالم السياحية. بعد الظهر ستزورون قصر تسفينغر بمجموعته الكبيرة من اللوحات والخزف والمنحوتات. في المساء، من المخطط زيارة دار أوبرا سمبر، حيث ستُعرض مساءً أوبرا الناي السحري لموزارت.\n\nفي 5 يونيو ستقومون برحلة إلى قصر بيلنتس الباروكي الواقع خارج المدينة، والمشهور حديقته بنباتاتها الغريبة. أثناء رحلة الحافلة التي تستغرق نصف ساعة، ستمرون فوق جسر الإلبه الشهير 'العجب الأزرق'. في 6 يونيو ستزورون القصر الملكي بقبته الخضراء. توجد بداخله أكثر من 3000 قطعة من فن الصياغة والمجوهرات. في المساء ستزورون كنيسة السيدة العذراء التي أُعيد بناؤها. هنا ينتظركم حفل موسيقي بموسيقى يوهان سيباستيان باخ. اليوم 7 يونيو متاح لتصرفكم الحر. ربما تودون التسوق أو المشاركة في رحلة إلى سويسرا الساكسونية القريبة.\n\nآمل أن تمنحكم هذه المعلومات المسبقة نظرة عامة عن الرحلة المخطط لها.\n\nستجدون معلومات أكثر تفصيلاً في كتيب برنامجنا، حيث ستجدون أيضاً أوقات المغادرة والوصول الدقيقة.\n\nمع خالص التحيات\nياسمين كريمر\nخدمة السفر كريمر",
  "cec6ec5c-83ec-461a-b5b2-bb249a1bed74": "السيدة شتاين المحترمة،\n\nبمناسبة محاضرتكم الأسبوع الماضي حول العواقب الصحية للتدخين لدى الشباب في إطار أسبوع صحة الشباب في كاسل، تحدثت معكم بإيجاز بالفعل. أود اليوم الاستفسار عمّا إذا كنتم مستعدين للتحدث أيضاً هنا عندنا في ماربورغ.\n\nفي إطار مشروع واسع النطاق في المدارس، سيُقام في يوليو يوم لمكافحة التدخين في قاعة المدينة. تتضمن الفعالية محاضرات وأيضاً ورش عمل ومنتديات نقاش، وتستمر من الساعة 9 حتى 18. بما أنكم خبيرة صحية معترف بها، ومواضيعكم تلامس الشباب تحديداً ومحاضراتكم واضحة جداً، نود ضمكم كمحاضِرة إلى برنامجنا.\n\nينبغي ألا تتجاوز مدة محاضرتكم 30 دقيقة. بعد محاضرتكم، نود منح الشباب المهتمين فرصة التحدث معكم حول موضوع العواقب الصحية للتدخين.\n\nبالطبع تكون تحت تصرفكم جميع الأجهزة التقنية الحديثة مثل الحاسوب أو جهاز عرض. يرجى إبلاغنا إذا احتجتم وسائل مساعدة أخرى. إذا أردتم نسخ أوراق عمل، يرجى إرسالها لنا قبل أيام قليلة حتى نتمكن من تجهيز النسخ لكم.\n\nنتوقع أن يحضر فعاليتنا حوالي 1000 شاب من المنطقة بأكملها. ستكون مشاركتكم في الفعالية إثراءً لبرنامجنا. لذا سنكون سعداء جداً بموافقتكم.\n\nمع خالص التحيات\nكارل-هاينتس هارتونغ",
  "4d84966a-dc16-477d-898e-803226e91756": "السيدة سابو المحترمة،\n\nشكراً جزيلاً على اهتمامكم بدوراتنا الألمانية. مرفق طيه استمارة التسجيل المطلوبة، يرجى إعادتها إلينا معبأة. مع التسجيل يرجى تحويل دفعة مقدمة بقيمة 200 يورو إلى حسابنا. ستجدون بيانات الحساب أسفل استمارة التسجيل. لتقييم أفضل لمعرفتكم المسبقة أرفقنا اختبار تحديد مستوى. إذا قمتم بتعبئة أوراق الاختبار وإعادتها إلينا مع التسجيل، فإنكم تساعدوننا في تخطيط الدورات. سيُجرى اختبار شفهي في أول يوم دراسي في مدرستنا. بذلك نتمكن من اختيار الدورة المناسبة لكم. بالإضافة إلى ذلك ستجدون في الأوراق استبياناً بخصوص اهتماماتكم الترفيهية. سنسعى لجعل إقامتكم في لايبزيغ ممتعة قدر الإمكان. أخيراً يرجى تعبئة ورقة الإقامة الخضراء. يمكنكم الاختيار بين فندق 3 نجوم، أو إقامة خاصة لدى عائلة مضيفة ألمانية، أو الإقامة في سكن طلابي. الخيار الأخير ممكن فقط خلال عطلات الجامعة - عادة من 15.2 إلى 15.4 ومن 15.7 إلى 15.10. يرجى أيضاً تحديد رغباتكم الغذائية - إفطار أو نصف إقامة. لكن يرجى ملاحظة أن السكن الطلابي يتيح فقط التموين الذاتي. بمجرد وصول تسجيلكم إلينا، ستحصلون على تأكيد تسجيل وخريطة للمدينة مع وصف الطريق، حتى تجدوا الطريق إلينا بسهولة. ستحصلون على عنوان إقامتكم قبل حوالي أسبوعين من بدء الدورة. لأي استفسارات إضافية، سكرتاريتنا في خدمتكم من الاثنين إلى الجمعة من 8 إلى 18.\n\nمع خالص التحيات\nغيرهارد ديتز\nالمدير",
  "1edcc63d-f03f-4a20-af93-23712b949f35": "السيدة سابو المحترمة،\n\nشكراً جزيلاً على اهتمامكم بدوراتنا الألمانية. مرفق طيه استمارة التسجيل المطلوبة، يرجى إعادتها إلينا معبأة.\n\nمع التسجيل يرجى تحويل دفعة مقدمة بقيمة 200 يورو إلى حسابنا. ستجدون بيانات الحساب أسفل استمارة التسجيل. من أجل تقييم أدق لمعرفتكم المسبقة أرفقنا اختبار تحديد مستوى.\n\nإذا قمتم بتعبئة أوراق الاختبار وإعادتها إلينا مع التسجيل، فإنكم تساعدوننا في تخطيط الدورات. سيُقام اختبار شفهي في أول يوم دراسي في مدرستنا. بذلك نتمكن من اختيار الدورة المناسبة لكم.\n\nبالإضافة إلى ذلك ستجدون في الأوراق استبياناً بخصوص اهتماماتكم الترفيهية، لأننا سنسعى لجعل إقامتكم في لايبزيغ ممتعة قدر الإمكان.\n\nأخيراً يرجى تعبئة ورقة الإقامة الخضراء. يمكنكم الاختيار بين فندق 3 نجوم، أو إقامة خاصة لدى عائلة مضيفة ألمانية، أو الإقامة في سكن طلابي. الخيار الأخير ممكن فقط خلال عطلات الجامعة. يرجى أيضاً تحديد رغباتكم الغذائية. لكن يرجى ملاحظة أن السكن الطلابي يتيح فقط التموين الذاتي.\n\nبمجرد وصول تسجيلكم إلينا، ستحصلون على تأكيد تسجيل وخريطة للمدينة، حتى تجدوا الطريق إلينا بسهولة. ستحصلون على عنوان إقامتكم قبل حوالي أسبوعين من بدء الدورة. لأي استفسارات إضافية، سكرتاريتنا في خدمتكم من الاثنين إلى الجمعة من 8 إلى 18.\n\nمع خالص التحيات\nغيرهارد ديتز",
  "a7fea463-902e-488e-8fee-2c5c391227dd": "سكان المبنى الأعزاء،\n\nلم يعد الشتاء بعيداً، لذا يجب تجهيز المبنى لمواجهته. لأجل هذا لا تزال هناك بعض الاستعدادات الضرورية.\n\nقبل بدء موسم التدفئة، ستُجرى أعمال صيانة في غرفة التدفئة. ستُنفَّذ هذه الأعمال في الفترة من 8.11 إلى 10.11. لضمان سير العمل بسلاسة، نطلب من جميع السكان إتاحة الوصول إلى مخازنهم وإزالة جميع الأغراض المخزنة (مثل الزلاجات) من غرفة التدفئة حتى هذا التاريخ.\n\nبالإضافة إلى ذلك، حدثت بعض الأضرار في المبنى خلال الصيف، ويجب إصلاحها قبل بداية الشتاء. انكسرت ثلاث نوافذ زجاجية؛ ويتعلق الأمر بمخزني الطابق السفلي رقم 5 و7. سيأتي عمال شركة الزجاج في 12.11 من أجل تركيب نوافذ زجاجية جديدة.\n\nنطلب منكم في هذه الأيام إتاحة الوصول إلى مخازنكم وعدم إعاقة المنطقة أمام النوافذ بأغراض.\n\nفي هذا الصدد، ندعو جميع سكان المبنى لمراعاة بعضهم البعض. فقد ازدادت الشكاوى في الآونة الأخيرة. يرجى تذكر نظام المبنى الداخلي.\n\nالضوضاء والموسيقى الصاخبة ممنوعة بعد الساعة 22، لكن يرجى الحرص في أي وقت من اليوم على ألا يشعر جيرانكم بالإزعاج. لعب كرة القدم وما شابه مسموح فقط في منطقة ملعب الأطفال خلف المبنى. في مواقف السيارات ومنطقة المدخل ممنوع اللعب بالكرات.\n\nنشكركم على تعاونكم ونبقى مع أطيب التحيات،\n\nإدارة المبنى",
  "123009f3-6299-4036-a571-522132e85c02": "السيد الدكتور دوبروميل المحترم،\n\nقرأت باهتمام بالغ إعلان وظيفتكم في صحيفة إيسن، الذي تبحثون فيه عن موظفة بدوام جزئي في متجر التحف الخاص بكم. يشدني تحمل مهمة ذات مسؤولية في متجر مرموق مثل متجركم. بعد إتمامي الثانوية العامة في مدرسة كرايس الثانوية في فيلبرت، بدأت تدريباً مهنياً لمدة ثلاث سنوات كنجارة لدى شركة آيشلبورر وشركاه، والتحقت بمدرسة كرايس المهنية في فيلبرت. بعد إتمام تدريبي المهني بنجاح، عملت لمدة عام لدى شركة شتوتس وشركاه لتصميم الأثاث في دوسلدورف. بعدها التحقت بجامعة العلوم التطبيقية في كولن في قسم تصميم الأثاث واكتشفت حبي للقطع الأثرية القديمة. تخصصي هو الترميم الدقيق للأثاث العتيق وإصلاحه، خاصة من طرازي بيدرماير وآر نوفو. بفضل خبرتي المهنية ودراستي، تمكنت من اكتساب معرفة واسعة فيما يتعلق بأنماط الأثاث وفن الصناعة في مختلف الحقب، سواء في شمال أوروبا أو جنوبها. تتيح لي دراستي وقتاً كافياً لتولي وظيفة بدوام جزئي تتناسب أيضاً مع قدراتي المهنية وميولي. لهذا السبب قررت الرد على إعلانكم، وأتقدم للوظيفة بدوام جزئي التي تعرضونها. أتطلع إلى مقابلة شخصية.\n\nمع خالص التحيات،\nسابينا هولتسينغر",
};

const merged = {};
for (const [exId, gaps] of Object.entries(explanations)) {
  merged[exId] = {
    translation: { text: passageTranslations[exId] },
    items: {},
  };
  for (const [gapNum, data] of Object.entries(gaps)) {
    merged[exId].items[gapNum] = {
      evidence_text: null,
      keyword: data.kw,
      explanation_correct: data.ex,
      explanation_wrong: data.ex,
      grammar_structure: data.gs,
      grammar_example: null,
      grammar_translation: null,
    };
  }
}

const ABBREV_ENDINGS = ["d.h.", "z.B.", "u.a.", "usw.", "bzw.", "ca.", "etc.", "Nr.", "Str.", "Dr.", "Mag.", "Prof.", "12.", "15.2.", "15.4.", "15.7.", "15.10."];
function isRealBoundary(text, i) {
  if (text[i] !== ".") return false;
  const after = text[i + 1];
  if (after !== undefined && after !== " " && after !== "\n") return false;
  const before = text.slice(Math.max(0, i - 8), i + 1);
  if (ABBREV_ENDINGS.some((a) => before.endsWith(a))) return false;
  // reject a lone digit + '.' (date/ordinal like "3." or "5.")
  if (/\d\.$/.test(before.slice(-2))) return false;
  return true;
}
function sentenceAround(passage, markerIdx, markerLen) {
  let start = 0;
  for (let i = markerIdx - 1; i >= 0; i--) {
    if (passage[i] === "\n") { start = i + 1; break; }
    if (isRealBoundary(passage, i)) { start = i + 1; break; }
  }
  let end = passage.length;
  for (let i = markerIdx + markerLen; i < passage.length; i++) {
    if (passage[i] === "\n") { end = i; break; }
    if (isRealBoundary(passage, i)) { end = i + 1; break; }
  }
  return passage.slice(start, end).trim().replace(/\s+/g, " ");
}

for (const [exId, aids] of Object.entries(merged)) {
  const src = passageData[exId];
  if (!src) { console.error("no source for", exId); continue; }
  const gapByNum = {};
  for (const g of src.gaps) gapByNum[g.gap_number] = g;
  for (const gap of src.gaps) {
    const k = String(gap.gap_number);
    const item = aids.items[k];
    if (!item) continue; // skipped gap (data issue) intentionally has no explanation; still try evidence
    const marker = `{{${k}}}`;
    const markerIdx = src.passage.indexOf(marker);
    if (markerIdx === -1) { console.error("marker not found", exId, k); continue; }
    let snippet = sentenceAround(src.passage, markerIdx, marker.length);
    snippet = snippet.replace(/\{\{(\d+)\}\}/g, (m, num) => {
      const g = gapByNum[Number(num)];
      return g ? g[`option_${g.correct}`] : m;
    });
    item.evidence_text = snippet;
  }
}

writeFileSync(
  "C:/Users/asus/AuraLingovia/scripts/learning-aids/sb_t1_batch3.json",
  JSON.stringify(merged)
);
console.log("Wrote sb_t1_batch3.json for", Object.keys(merged).length, "exercises");

let issues = 0;
let skippedGaps = [];
for (const [exId, aids] of Object.entries(merged)) {
  const src = passageData[exId];
  if (!src) { issues++; continue; }
  if (!aids.translation.text) { console.error("missing translation", exId); issues++; }
  for (const gap of src.gaps) {
    const k = String(gap.gap_number);
    const item = aids.items[k];
    if (!item) { skippedGaps.push(exId + "#" + k); continue; }
    if (!item.keyword || !item.explanation_correct || item.explanation_correct.length < 30 || item.evidence_text.includes("{{")) {
      console.error("incomplete/bad", exId, k, item.evidence_text?.slice(0,50));
      issues++;
    }
  }
}
console.log("issues:", issues, "| intentionally skipped gaps:", skippedGaps);
